#define NX_SECURE_SOURCE_CODE

#include "nx_secure_dtls.h"

/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _nx_secure_dtls_server_cookie_secret_set            PORTABLE C      */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function sets the secret from which a DTLS server derives the  */
/*    keys of its HelloVerifyRequest cookies, in place of drawing them    */
/*    from NX_RAND. An application with a source of true randomness or a  */
/*    key store should use it. A length of zero returns the server to     */
/*    NX_RAND. Cookies issued before the call no longer verify.           */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    server_ptr                            DTLS server control block     */
/*    secret                                Secret                        */
/*    secret_length                         Length of secret, at most     */
/*                                            NX_SECURE_DTLS_COOKIE_      */
/*                                            SECRET_SIZE                 */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    status                                Completion status             */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    tx_mutex_get                          Get protection mutex          */
/*    tx_mutex_put                          Put protection mutex          */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    Application Code                                                    */
/*                                                                        */
/**************************************************************************/
UINT _nx_secure_dtls_server_cookie_secret_set(NX_SECURE_DTLS_SERVER *server_ptr,
                                              const UCHAR *secret, UINT secret_length)
{
#ifdef NX_SECURE_ENABLE_DTLS
UINT status = NX_INVALID_PARAMETERS;

    if (secret_length <= NX_SECURE_DTLS_COOKIE_SECRET_SIZE)
    {

        /* Get the protection. */
        tx_mutex_get(&_nx_secure_tls_protection, TX_WAIT_FOREVER);

        NX_SECURE_MEMSET(server_ptr -> nx_dtls_server_cookie_master_secret, 0,
                         sizeof(server_ptr -> nx_dtls_server_cookie_master_secret));
        if (secret_length > 0u)
        {
            NX_SECURE_MEMCPY(server_ptr -> nx_dtls_server_cookie_master_secret, secret, secret_length); /* Use case of memcpy is verified. */
        }
        server_ptr -> nx_dtls_server_cookie_master_secret_length = secret_length;
        server_ptr -> nx_dtls_server_cookie_derivation_count = 0u;

        /* Replace the current secrets when the next ClientHello arrives. */
        server_ptr -> nx_dtls_server_cookie_ready = NX_FALSE;

        /* Release the protection. */
        tx_mutex_put(&_nx_secure_tls_protection);

        status = NX_SUCCESS;
    }

    return(status);
#else
    NX_PARAMETER_NOT_USED(server_ptr);
    NX_PARAMETER_NOT_USED(secret);
    NX_PARAMETER_NOT_USED(secret_length);

    return(NX_NOT_SUPPORTED);
#endif /* NX_SECURE_ENABLE_DTLS */
}
